    .table {
        background: transparent !important;
        table-layout: fixed;
        border: 0 !important;
        color: #000000;
        border-collapse: separate;   /* sin bordes no necesitas collapse */
        border-spacing: 0;           /* elimina separación entre celdas */
        font-family: Verdana;
        overflow: hidden;
    }

    /* Encabezados principales */
    .table th {
        color: #ffffff !important;
        text-align: center;
        padding: 0.6em !important;
        border: 0 !important;
        outline: 0;
        font-family: Verdanab;
        font-size: 13px;
        box-shadow: none;
    }

    /* Celdas de datos */
    .table td {
        color: #1e2a41;
        padding: 10px 8px;
        border: 0 !important;
        outline: 0;
        vertical-align: middle;
        text-align: left;
        font-size: 13px;
        box-shadow: none;
    }
    @media (max-width: 768px) {
        .table {
            font-size: 10px;
        }
        .table thead th,
        .table td {
            padding: 6px 4px;
        }
    }
    .table1 {
        table-layout: fixed;
        border: hidden !important;
        color: #000000;
        width: auto !important;
        border-collapse: collapse;
        font-family:Verdana;
        border-radius: 12px 12px 0 0 !important;
        overflow: hidden;
    }
    /* Encabezados principales - degradado VERTICAL dorado */
    .table1 th {
        background: linear-gradient(to bottom, #e6cc80, #d4a52a) !important;
        color: #3a2e0a !important;
        text-align: center;
        padding: 0.6em !important;
        border: 1px solid #d4d4d4 !important;
        font-family:Verdanab;
        font-size: 13px;
        letter-spacing: 0.3px;
    }
    /* Border-radius en la primera fila del encabezado */
    .table1 thead tr:first-child th:first-child {
        border-top-left-radius: 12px !important;
    }

    .table1 thead tr:first-child th:last-child {
        border-top-right-radius: 12px !important;
    }

    /* Subencabezados (P / E) - gris muy claro con texto negro */
    .table1 thead td {
        background: #f0f0f0 !important;
        color: #000000 !important;
        font-weight: bold;
        text-align: center;
        padding: 0.4em 2px !important;
        border: 1px solid #d4d4d4 !important;
        font-size: 10px;
        font-family:verdanab;
    }

    /* Filas de categorías (Planificación, Implementación, etc.) */
    .table1 tr[style*="background:#2f74b5"] td {
        background: linear-gradient(to bottom, #e6cc80, #d4a52a) !important;
        color: #3a2e0a !important;
        font-size: 14px;
        padding: 0.6em 12px !important;
        border: 1px solid #d4d4d4 !important;
        letter-spacing: 0.5px;
    }

    /* Celdas de datos - se mantiene exactamente como estaba */
    .table1 td {
        text-align: left;
        padding: 1em;
        border: 1px solid #d4d4d4 !important;
        vertical-align: middle !important;
        background-color: #fdfdfd;
    }

    /* ============================================ */
    /* PRIMERA COLUMNA - COMPLETAMENTE TRANSPARENTE */
    /* ============================================ */
    .table1 tbody td:nth-child(1),
    .table1 tbody tr:nth-child(even) td:nth-child(1),
    .table1 tbody td:nth-child(1) * {
        background-color: transparent !important;
        background: transparent !important;
    }

    /* ============================================ */
    /* SEGUNDA COLUMNA - COMPLETAMENTE TRANSPARENTE */
    /* ============================================ */
    .table1 tbody td:nth-child(2),
    .table1 tbody tr:nth-child(even) td:nth-child(2),
    .table1 tbody td:nth-child(2) * {
        background-color: transparent !important;
        background: transparent !important;
    }


    /* Estilo para los íconos de "agregar" (glyphicon) */
    .table1 .glyphicon-plus {
        color: #ffffff !important;
        background: rgba(255, 255, 255, 0.15);
        padding: 4px 8px;
        border-radius: 20px;
        font-size: 14px;
        transition: 0.2s;
    }

    /* Porcentajes al lado de los títulos */
    .table1 span[id^="porcentaje_"] {
        background: rgba(255, 255, 255, 0.2);
        padding: 2px 10px;
        border-radius: 30px;
        font-weight: 700;
        font-size: 13px;
        margin-left: 10px;
    }


    /* ============================================ */
    /* ICONOS FONTAWESOME - SIN NINGÚN COLOR DE FONDO */
    /* ============================================ */
    .table1 .fa,
    .table1 .fas,
    .table1 .far,
    .table1 .fab,
    .table1 .glyphicon {
        background: transparent !important;
        background-color: transparent !important;
    }

    /* Botones con iconos - sin fondo */
    .table1 button,
    .table1 .btn,
    .table1 .X1 {
        background: transparent !important;
        background-color: transparent !important;
        border: none !important;
        box-shadow: none !important;
    }
.table2 {
    table-layout: fixed;
    border: hidden !important;
    color: #000000;
    width: auto !important;
    border-collapse: collapse;
    font-family: Verdana;
    border-radius: 12px 12px 0 0 !important;
    overflow: hidden;
    line-height: 24px;
}

/* Encabezados principales - degradado VERTICAL */
.table2 thead th {
    border: 1px solid #d4d4d4 !important;
    font-family: Verdanab;
    font-size: 12px;
    background: linear-gradient(to bottom, #8a6d1f, #5c4608);
    color: #ffffff;
    text-align: center;
    padding: 5px 2px;
    border: 1px solid #c9a52a;
    letter-spacing: 0.3px;
}

/* Subencabezados (P / E) - degradado VERTICAL más suave */
.table2 thead td {
    background: linear-gradient(to bottom, #f0e6c8, #e6d8b0);
    color: #000000;
    font-weight: bold;
    text-align: center;
    padding: 6px 2px;
    border: 1px solid #d4c088;
    font-size: 12px;
}

/* Filas de categorías (Planificación, Implementación, etc.) - degradado VERTICAL */
.table2 tr[style*="background:#2f74b5"] td {
    background: linear-gradient(to bottom, #e6cc80, #d4a52a);
    color: #3a2e0a !important;
    font-weight: 700;
    font-size: 12px;
    padding: 10px 12px;
    border: 1px solid #c9a52a;
    letter-spacing: 0.5px;
}

/* ===== Celdas de datos ===== */
.table2 td {
    background-color: #ffffff;
    color: #2a2a2a;
    padding: 10px 8px;
    border: 1px solid #e0d4b8;
    vertical-align: middle;
    text-align: left;
    font-size: 12px;
    line-height: 1.5;
    letter-spacing: 0.2px;
    transition: background-color 0.25s ease, color 0.25s ease;
}

/* Hover suave al pasar el mouse por la fila */
.table2 tbody tr:hover td {
    background-color: #faf3e0;
    color: #000000;
}

/* Primeras 4 columnas centradas y con más peso */
.table2 tbody td:nth-child(1),
.table2 tbody td:nth-child(2),
.table2 tbody td:nth-child(3),
.table2 tbody td:nth-child(4) {
    text-align: center;
    font-weight: 600;
}

/* Estilo para los íconos de "agregar" (glyphicon) */
.table2 .glyphicon-plus {
    color: #ffffff !important;
    background: rgba(255, 255, 255, 0.2);
    padding: 4px 8px;
    border-radius: 20px;
    font-size: 14px;
    transition: 0.2s;
}

.table2 .glyphicon-plus:hover {
    background: rgba(255, 255, 255, 0.4);
    transform: scale(1.1);
}

/* Porcentajes al lado de los títulos */
.table2 span[id^="porcentaje_"] {
    background: rgba(255, 255, 255, 0.2);
    padding: 2px 10px;
    border-radius: 30px;
    font-weight: 700;
    font-size: 13px;
    margin-left: 10px;
}

/* Ajuste para pantallas pequeñas */
@media (max-width: 768px) {
    .table2 {
        font-size: 10px;
    }
    .table2 th,
    .table2 td {
        padding: 6px 4px;
    }
    .table2 tr[style*="background:#2f74b5"] td {
        font-size: 12px;
    }
}  
