    [data-title]:hover:after {
        opacity: 1;
        transition: all 0.1s ease 0.5s;
        visibility: visible;
    }

    [data-title]:after {
        content: attr(data-title);
        position: absolute;
        top: -3em;
        left: 50%;
        transform: translateX(-50%);
        background-color: #ffffff;
        color: #333333;
        font-size: 14px;
        font-family: verdanab;
        padding: 6px 10px;
        text-align: center;
        white-space: nowrap;
        box-shadow: 1px 1px 3px #222222;
        border: 1px solid #333333;
        border-radius: 0;
        z-index: 99999;
        opacity: 0;
        visibility: hidden;
        pointer-events: none;
    }

    /* 🔑 CLAVE: quitar el overflow de la tabla y sus contenedores */
    table,
    thead,
    tbody,
    tr,
    td,
    .table,
    .table-responsive,
    [id^="documentos"] {
        overflow: visible !important;
    }

    /* Si la tabla tiene un contenedor con scroll, permitir que el tooltip salga */
    .table-responsive {
        overflow-x: auto !important;  /* deja el scroll horizontal pero... */
        overflow-y: visible !important; /* ...permite que los tooltips salgan por arriba */
    }
