    input[type="radio"] { 
        display:inline-block;
        -webkit-appearance: none;
        -moz-appearance: none;
        width:0px;
        height:0px;
        background:url(imagen_checkbox.png) left top no-repeat;                
        cursor:pointer;
        float:right!important;
    }
    .radio label {
        display: inline-block;
        position: relative;
        float:center!important;
        margin:-2em!important;
    }
    #check1::before {
        content: "";
        display: inline-block;
        position: absolute;
        width: 24px;
        height: 24px;
        background-color:transparent;
        border:1px solid #71788e;
        text-align:center;
        margin-top:-1.6em;
        margin-left:2.2em;
    }
    #check1::after {
        display: inline-block;
        position: absolute;
        font-size:26px!important;
        color:#e7744f;
        margin-left:29px;
        margin-top:-24px;
    }
    #check4::before {
        content: "";
        display: inline-block;
        position: absolute;
        width: 24px;
        height: 24px;
        background-color:transparent;
        border:1px solid #006699;
        text-align:center;
        margin-top:-1.6em;
        margin-left:2.2em;
    }
    #check4::after {
        display: inline-block;
        position: absolute;
        font-size:26px!important;
        color:#006699;
        margin-left:30px;
        margin-top:-24px;
    }
    .radio input[type="radio"]:checked + label::after {
        font-family: 'FontAwesome';
        content: "\f00c";
    } 
    .contenedor {
        margin: 2rem auto;
        border:0;
        width:100%;
        max-width:200em;
        background:transparent;
        overflow-y: hidden;
        overflow-x: auto;
        box-sizing: border-box;
        padding:0 1rem;
        z-index:-1!important;
    } 
    .contenedor::-webkit-scrollbar {
        -webkit-appearance: none;
    }
    .contenedor::-webkit-scrollbar:vertical {
        width:10px;
    }
    .contenedor::-webkit-scrollbar-button:increment,.contenedor::-webkit-scrollbar-button {
        display: none;
    } 
    .contenedor::-webkit-scrollbar:horizontal {
        height: 10px;
    }
    .contenedor::-webkit-scrollbar-thumb {
        background-color: #797979;
        border-radius: 20px;
        border: 2px solid #f1f2f3;
    }

    .contenedor::-webkit-scrollbar-track {
        border-radius: 10px;  
    }
