    /* Cuadro central - más arriba */
    .sidebar-central {
        background: white;
        width: 400px;
        max-width: 90%;
        max-height: 70vh;
        border-radius: 12px;
        padding: 25px;
        box-shadow: 0 8px 30px rgba(0,0,0,0.2);
        overflow-y: auto;
        position: relative;
        margin: 0 auto;
        animation: slideDown 0.3s ease-out;
        border: 1px solid rgba(255,255,255,0.3);
    }
    @keyframes slideDown {
        from {
            opacity: 0;
            transform: translateY(-20px);
        }
        to {
            opacity: 1;
            transform: translateY(0);
        }
    }
    /* Botón cerrar (X) */
