        $(document).on('click', '.eliminar_In', (e) => {
            e.preventDefault();
            const element = $(this)[0].activeElement.parentElement.parentElement;
            const id = $(element).attr('taskId1');
            const indicador = $(element).attr('taskId');
            $("#costumModal8").modal("show");
            $('#id_In').html(id);
            $('#indicador_In').html(indicador);
            $(".delete").on('click', function(event) { 
                var id_in_osteo = document.getElementById("id_In").innerHTML;
                $.ajax({
                    type: "post",
                    url: "../editar_pve.php",
                    data: "id_in_osteo=" + id_in_osteo,
                    success: function(response) {
                        indicadores(); 
                    }
                });
            });
        });
        $(document).on('click', '.editar_In', (e) => {
            
