                   let id= '';
                   let Tipo= '';
                   let Definicion= '';
                   let Interpretacion= '';
                   let Fuente= '';
                   let Indicador= '';
                   let Numerador= '';
                   let Denominador= '';
                   let Meta= '';
                   let Resultado= '';
                   tasks.forEach(task => {
                        id += `${task.id}`,
                        Tipo += `${task.Tipo}`,
                        Definicion += `${task.Definicion}`,
                        Interpretacion += `${task.Interpretacion}`,
                        Fuente += `${task.Fuente}`
                        Indicador += `${task.Indicador}`
                        Numerador += `${task.Numerador}`
                        Denominador += `${task.Denominador}`
                        Meta += `${task.Meta}`
                        Resultado += `${task.Resultado}`
                   });
