                document.getElementById("Tipo_e").value = (Tipo);
                document.getElementById("Definicion_e").value = (Definicion);
                document.getElementById("Interpretacion_e").value = (Interpretacion);
                document.getElementById("Fuente_e").value = (Fuente);
                document.getElementById("Indicador_e").value = (Indicador);
                document.getElementById("Numerador_e").value = (Numerador);
                document.getElementById("Denominador_e").value = (Denominador);
                document.getElementById("Meta_e").value = (Meta);
                document.getElementById("Resultado_e").value = (Resultado);
