                        const postData = {
                            id_e_osteo:$('#id_e').val(),
                            Tipo_e_osteo:$('#Tipo_e').val(),
                            Definicion_e_osteo:$('#Definicion_e').val(),
                            Interpretacion_e_osteo:$('#Interpretacion_e').val(),
                            Fuente_e_osteo:$('#Fuente_e').val(),
                            Indicador_e_osteo:$('#Indicador_e').val(),
                            Numerador_e_osteo:$('#Numerador_e').val(),
                            Denominador_e_osteo:$('#Denominador_e').val(),
                            Meta_e_osteo:$('#Meta_e').val(),
                            Resultado_e_osteo:$('#Resultado_e').val()
                        };
                        const url = '../editar_pve.php';
                        $.post(url,  postData, (response) => {
                            indicadores()
                            $("#costumModal9").modal("hide");
                            
                        });
