        indicadores();
        function indicadores() {
            var id_admin = '<?php echo $id_admin ?>';
            var Codigo = '<?php echo $Codigo ?>';
            $.ajax({
                type: "post",
                url: "../item_indicadores_osteo.php",
                data: "Codigo=" + Codigo  + "&id_admin=" + id_admin,
                success: function (response) {
                const tasks = JSON.parse(response);
                let indicadores = '';
                tasks.forEach(task => {
                    indicadores += `
                    <tr id="textarea" taskId="${task.Tipo}" taskId1="${task.id}" style="font-family:verdana;font-size:13px!important;text-align:left">
                        <td style="font-family:verdanab">${task.Tipo}<br><button class="eliminar_In" data-title="Eliminar" style="float:left;left:0em"><span class="fa fa-trash"></span></button><button class="editar_In" data-title="Editar" style="float:left;left:1em"><span class="fa fa-pencil"></span></button><button class="grafica_In" data-title="Tendencias" style="float:left;left:2em"><span class="fa fa-line-chart"></span></button></td> 
                        <td style="text-align:left">${task.Definicion}</td> 
                        <td style="text-align:left">${task.Interpretacion}</td> 
                        <td style="text-align:left">${task.Fuente}</td> 
                        <td style="text-align:center">${task.Indicador} = <div class="fraction"><span class="fup">${task.Numerador}</span><span class="bar">/</span> <span class="fdn">${task.Denominador}</span></span></div> * 100</td> 
                        <td style="text-align:center;vertical-align:middle!important"><button class="I1" style="color:#006699;font-family:verdana!important;font-size:13px!important" value="">${task.Meta}%</button></td> 
                        <td style="text-align:center;vertical-align:middle!important">${task.Resultado}%</td>
                    </tr> `
                });
                $('#indicadores').html(indicadores);
                },   
            });
        }
