            function procedimientos() {
                Codigo = '<?php echo $Codigo ?>';
                $.ajax({
                    type: "post",
                    url: "../text_osteo.php",
                    data: "Codigo=" + Codigo,
                    success: function (response) {
                    const tasks = JSON.parse(response);
                    let Objetivo= '';
                    let Alcance= '';
                    let Definicion= '';
                    let Responsabilidades= '';
                    let Planear= '';
                    let Hacer= '';
                    let Verificar= '';
                    let Corregir= '';
                    tasks.forEach(task => {
                        Objetivo += `${task.Objetivo}`,
                        Alcance += `${task.Alcance}`,
                        Definicion += `${task.Definicion}`,
                        Responsabilidades += `${task.Responsabilidades}`,
                        Planear += `${task.Planear}`,
                        Hacer += `${task.Hacer}`
                        Verificar += `${task.Verificar}`
                        Corregir += `${task.Corregir}`
                    });
                    document.getElementById('objetivo').innerHTML = Objetivo;
                    document.getElementById('alcance').innerHTML = Alcance;
                    document.getElementById('definicion_T').innerHTML = Definicion;
                    document.getElementById('responsabilidades_T').innerHTML = Responsabilidades;
                    document.getElementById('planear').innerHTML = Planear;
                    document.getElementById('hacer_P').innerHTML = Hacer;
                    document.getElementById('verificar').innerHTML = Verificar;
                    document.getElementById('corregir').innerHTML = Corregir;
                    var Objetivo0 = Objetivo.replace(/<br [/][>]/g, "");
                    document.getElementById("objetivoE").value = (Objetivo0);
                    var Alcance0 = Alcance.replace(/<br [/][>]/g, "");
                    document.getElementById("alcanceE").value = (Alcance0);
                    var Definicion0 = Definicion.replace(/<br [/][>]/g, "");
                    document.getElementById("definicionE").value = (Definicion0);
                    var Responsabilidades0 = Responsabilidades.replace(/<br [/][>]/g, "");
                    document.getElementById("responsabilidadesE").value = (Responsabilidades0);
                    var Planear0 = Planear.replace(/<br [/][>]/g, "");
                    document.getElementById("planearE").value = (Planear0);
                    var Hacer0 = Hacer.replace(/<br [/][>]/g, "");
                    document.getElementById("hacerE").value = (Hacer0);
                    var Verificar0 = Verificar.replace(/<br [/][>]/g, "");
                    document.getElementById("verificarE").value = (Verificar0);
                    var Corregir0 = Corregir.replace(/<br [/][>]/g, "");
                    document.getElementById("corregirE").value = (Corregir0);
                    }
                });
            }
