        $(document).on('click', '.eliminar_P', (e) => {
            e.preventDefault();
            const element = $(this)[0].activeElement.parentElement.parentElement;
            const id = $(element).attr('taskId1');
            const actividad = $(element).attr('taskId2');
            $("#costumModal1").modal("show");
            $('#id_C').html(id);
            $('#actividad_C').html(actividad);
            $(".delete").on('click', function(event) { 
                var id_P = document.getElementById("id_C").innerHTML;
                $.ajax({
                    type: "post",
                    url: "../eliminar.php",
                    data: "id_P4=" + id_P,
                    success: function(response) {
                       planificacion(); 
                       consolidado();
                       
                    }
                });
            }); 
        });
        $(document).on('click', '.editar_P', (e) => {
            const element = $(this)[0].activeElement.parentElement.parentElement;
            const id = $(element).attr('taskId1');
            $("#costumModal2").modal("show");
            $.ajax({
                type: "post",
                url: "../datosplanificacion.php",
                data: "id4=" + id,
                success: function (response) {
                   const tasks = JSON.parse(response);
                   let id= '';
                   let Actividades= '';
                   let Responsabilidades= '';
                   let Periodicidad= '';
                   let Observaciones= '';
                   tasks.forEach(task => {
                        id += `${task.id}`,
                        Actividades += `${task.Actividades}`,
                        Responsabilidades += `${task.Responsabilidades}`,
                        Periodicidad += `${task.Periodicidad}`,
                        Observaciones += `${task.Observaciones}`
                   });
                document.getElementById("id_P_e").value = (id);
                document.getElementById("Actividades_P_e").value = (Actividades);
                document.getElementById("Responsabilidades_P_e").value = (Responsabilidades);
                document.getElementById("Periodicidad_P_e").value = (Periodicidad);
                document.getElementById("Observaciones_P_e").value = (Observaciones);
                $('#form_P_editar').submit(e => {
                        e.preventDefault();
                        const postData = {
                            id_P_e4:$('#id_P_e').val(),
                            Actividades_P_e:$('#Actividades_P_e').val(),
                            Responsabilidades_P_e:$('#Responsabilidades_P_e').val(),
                            Periodicidad_P_e:$('#Periodicidad_P_e').val(),
                            Observaciones_P_e:$('#Observaciones_P_e').val(),
                        };
                        const url = '../editar_pve.php';
                        $.post(url,  postData, (response) => {
                            planificacion();
                            consolidado();
                            $("#costumModal2").modal("hide");
                            
                        });
                    }); 
                }      
            }); 
        }); 
         $(document).on('change', '#certificada_', (e) => {
            var certificada_ = $('#certificada_').val();
            document.getElementById("certificada_pdf").value = (certificada_);
        })
        severidad();
        function severidad() {
            var id_admin = '<?php echo $Codigo ?>';
            $.ajax({
                type: "post",
                url: "../severidad.php",
                data: "id_admin=" + id_admin,
                success: function(response) {
                    const tasks0 = JSON.parse(response);
                    tasks0.push({"certificada":" "});
                    const tasks = tasks0.reverse();
                    let template = '';
                    tasks.forEach(task => {
                    template += `<option>${task.certificada}</option>`
                });
                $('#certificada_').html(template);
          
                }
            });
        };    
        planificacion();
        function planificacion() {
            var Codigo = '<?php echo $Codigo ?>';
            var id_admin = '<?php echo $id_admin ?>';
            var id = '<?php echo $id ?>';
            $.ajax({
                type: "post",
                url: "../item_ag_P4.php",
                data: "Codigo=" + Codigo  + "&id_admin=" + id_admin + "&id=" + id,
                success: function (response) {
                const tasks = JSON.parse(response);
                let Template = '';
                tasks.forEach(task => {
                    Template += `
                    <tr id="textarea" taskId1="${task.id}" taskId2="${task.Actividades}">
                        <td id="td" align="left" style="font-size:12px!important">${task.Actividades}<br><button class="eliminar_P" data-title="Eliminar" style="float:left;left:0em;display:${task.Boton2}!important"><span class="fa fa-trash"></span></button><button class="editar_P" data-title="Editar" style="float:left;left:1em;display:${task.Boton2}!important"><span class="fa fa-pencil"></span></button></td>
                        <td id="td" style="font-size:12px!important">${task.Responsabilidades}</td>
                        <td id="td" style="font-size:12px!important">${task.Periodicidad}</td>
                        <td class="registro2"><p style="font-family:verdanab;margin-bottom:-2em">${task.P1}</p><button class="P1" value="" ${task.Boton}/></button></td>
                        <td class="registro2"><p style="font-family:verdanab;margin-bottom:-2em">${task.E1}</p><button class="E1" value="" ${task.Boton}/></button></td>
                        <td class="registro2"><p style="font-family:verdanab;margin-bottom:-2em">${task.P2}</p><button class="P2" value="" ${task.Boton}/></button></td>
                        <td class="registro2"><p style="font-family:verdanab;margin-bottom:-2em">${task.E2}</p><button class="E2" value="" ${task.Boton}/></button></td>
                        <td class="registro2"><p style="font-family:verdanab;margin-bottom:-2em">${task.P3}</p><button class="P3" value="" ${task.Boton}/></button></td>
                        <td class="registro2"><p style="font-family:verdanab;margin-bottom:-2em">${task.E3}</p><button class="E3" value="" ${task.Boton}/></button></td>
                        <td class="registro2"><p style="font-family:verdanab;margin-bottom:-2em">${task.P4}</p><button class="P4" value="" ${task.Boton}/></button></td>
                        <td class="registro2"><p style="font-family:verdanab;margin-bottom:-2em">${task.E4}</p><button class="E4" value="" ${task.Boton}/></button></td>
                        <td class="registro2"><p style="font-family:verdanab;margin-bottom:-2em">${task.P5}</p><button class="P5" value="" ${task.Boton}/></button></td>
