        $('#boton_elementos').click(function(event) {  
            event.preventDefault();
            var id_admin = <?php echo $id_admin ?>;
            var Elemento = $('#Elemento').val();
            var Elemento_titulo = $('#Elemento_titulo').val();
            var formData = new FormData();
            var files = $('#file-836')[0].files[0];
            if (!files) return alert('Selecciona archivo');
            $(this).prop('disabled', true).html('Subiendo...');
            $('<div class="progress mt-2"><div class="progress-bar" style="width: 0%">0%</div></div>')
                .insertAfter(this);
            formData.append('file',files);
            formData.append('id_admin',id_admin);
            formData.append('sve',4);
            formData.append('Elemento',Elemento);
            formData.append('Elemento_titulo',Elemento_titulo);
            $('#content').html('<div class="loading"><img src="../imagine/carga6.gif" style="margin-top:20%" /></div>');
            $.ajax({
                url: '../insertar_img.php',
                type: 'post',
                data: formData,
                contentType: false,
                processData: false,
                xhr: function() {
                    const xhr = new XMLHttpRequest();
                    xhr.upload.addEventListener('progress', function(e) {
                        if (e.lengthComputable) {
                            const percent = (e.loaded / e.total) * 100;
                            $('.progress-bar').css('width', percent + '%').text(percent.toFixed(0) + '%');
                        }
                    });
                    return xhr;
                },
                success: function(response) {
                    $("#costumModal20").modal("hide");
                    Tasks_elemento();
                    document.getElementById("form_elementos").reset();
                },
                rror: function() {
                    alert('Error de conexión');
                },
                complete: function() {
                    $('#boton_recursos').prop('disabled', false).html('Guardar Recurso');
                    $('.progress').remove();
                }
            });
            return false;
        });
