        function metas() {
             $.ajax({
                type: "post",
                url: "../datos_metas_osteo.php",
                data: "Codigo=" + Codigo,
                success: function (response) {
                   const tasks = JSON.parse(response);
                   let id= '';
                   let Enero= '';
                   let Febrero= '';
                   let Marzo= '';
                   let Abril= '';
                   let Mayo= '';
                   let Junio= '';
                   let Julio= '';
                   let Agosto= '';
                   let Septiembre= '';
                   let Octubre= '';
                   let Noviembre= '';
                   let Diciembre= '';
                   tasks.forEach(task => {
                        id += `${task.id}`
                        Enero += `${task.Enero}`
                        Febrero += `${task.Febrero}`
                        Marzo += `${task.Marzo}`
                        Abril += `${task.Abril}`
                        Mayo += `${task.Mayo}`
                        Junio += `${task.Junio}`
                        Julio += `${task.Julio}`
                        Agosto += `${task.Agosto}`
                        Septiembre += `${task.Septiembre}`
                        Octubre += `${task.Octubre}`
                        Noviembre += `${task.Noviembre}`
                        Diciembre += `${task.Diciembre}`

                   });
                document.getElementById("Enero_m1").value = (Enero);
                document.getElementById("Febrero_m1").value = (Febrero);
                document.getElementById("Marzo_m1").value = (Marzo);
                document.getElementById("Abril_m1").value = (Abril);
                document.getElementById("Mayo_m1").value = (Mayo);
                document.getElementById("Junio_m1").value = (Junio);
                document.getElementById("Julio_m1").value = (Julio);
                document.getElementById("Agosto_m1").value = (Agosto);
                document.getElementById("Septiembre_m1").value = (Septiembre);
                document.getElementById("Octubre_m1").value = (Octubre);
                document.getElementById("Noviembre_m1").value = (Noviembre);
                document.getElementById("Diciembre_m1").value = (Diciembre);
                }      
            }); 
        }  
        

