        function fetchTasks1() {
            var Codigo = '<?php echo $Codigo ?>';
            $.ajax({
                type: "post",
                url: "../diagnosticoO.inc.php",
                data: "Codigo=" + Codigo,
                success: function(response) {
                    const tasks = JSON.parse(response);
                    let template = '';
                    tasks.forEach(task => {
                        template += `<tr id="textarea" taskId1="${task.id}" taskId2="${task.Nombre}">
                                    <td id="borderout" style="padding:1em;width:10%"><button class="task-delete-t" data-title="Eliminar"><span class="fa fa-trash"></span></button><button class="editar_t" data-title="Editar"><span class="fa fa-pencil"></span></button></td>
                                    <td style="text-align:center;font-family:verdanab;width:30%">${task.numeracion}</td>

                                   </tr> `
                    });
                    $('#diagnosticoO').html(template);
                }
            });
        }
            
            
