let todosLosTasks = [];
let paginaActual = 1;
const POR_PAGINA = 100;

reporte();

function reporte() {
    var Codigo = '<?php echo $Codigo ?>';
    $.ajax({
        type: "post",
        url: "../reporte13.php",
        data: "Codigo=" + Codigo,
        success: function (response) {
            todosLosTasks = JSON.parse(response);
            paginaActual = 1;
            renderPagina();
            renderPaginador();
        }
    });
}

function renderPagina() {
    const inicio = (paginaActual - 1) * POR_PAGINA;
    const fin = inicio + POR_PAGINA;
    const tasks = todosLosTasks.slice(inicio, fin);

    let Template = '';
    tasks.forEach(task => {
        Template += `
        <tr id="textarea" taskId1="${task.id}" taskId2="${task.Nombre}">
            <td id="borderout"><button class="task-delete-t" data-title="Eliminar" style="font-size:14px"><span class="fa fa-trash"></span></td>
            <td id="borderout"><button class="editar_t" data-title="Editar" style="font-size:14px"><span class="fa fa-pencil"></span></button></td>
            <td id="borderout"><button class="pdf_reporte" data-title="Notificación" style="color:${task.Notificacion}!important;font-size:16px"><span class="fa fa-check"></span></button></td>
            <td style="text-align:center;font-family:verdanab">${task.numeracion}</td>
            <td style="text-align:center;font-family:verdanab">${task.GES}</td>
            <td style="text-align:center;font-family:verdanab;background:${task.R_C}">${task.Riesgo}</td>
            <td style="text-align:left;font-family:verdanab">${task.Nombre}</td>
            <td style="text-align:center;font-family:verdanab">${task.Cedula}</td>
            <td style="text-align:left;font-family:verdanab">${task.Genero}</td>
            <td style="text-align:center;font-family:verdanab">${task.Edad}</td>
            <td style="text-align:left;font-family:verdanab">${task.Empresa}</td>
            <td style="text-align:left;font-family:verdanab">${task.Costo}</td>
            <td style="text-align:left;font-family:verdanab">${task.Sede}</td>
            <td style="text-align:left;font-family:verdanab">${task.Antiguedad_1}</td>
            <td style="text-align:left;font-family:verdanab">${task.Cargo}</td>
            <td style="text-align:left;font-family:verdanab">${task.Antiguedad_2}</td>
            <td style="text-align:center;font-family:verdanab">${task.Horas}</td>
            <td style="text-align:left;font-family:verdanab">${task.Email}</td>
            <td style="text-align:left;font-family:verdanab">${task.Celular}</td>
            <td style="text-align:center;font-family:verdanab">${task.P6}</td>
            <td style="text-align:center;font-family:verdanab">${task.P7}</td>
            <td style="text-align:center;font-family:verdanab;background:${task.Riesgo1}">${task.P8}</td>
            <td style="text-align:center;font-family:verdanab;background:${task.Riesgo2}">${task.P9}</td>
            <td style="text-align:center;font-family:verdanab;background:${task.Riesgo3}">${task.P10}</td>
            <td style="text-align:center;font-family:verdanab;background:${task.Riesgo4}">${task.P11}</td>
            <td style="text-align:center;font-family:verdanab;background:${task.Riesgo5}">${task.P12}</td>
            <td style="text-align:center;font-family:verdanab;background:${task.Riesgo6}">${task.P13}</td>
            <td style="text-align:center;font-family:verdanab;background:${task.Riesgo7}">${task.P14}</td>
            <td style="text-align:center;font-family:verdanab;background:${task.Riesgo8}">${task.P15}</td>
            <td style="text-align:center;font-family:verdanab;background:${task.Riesgo9}">${task.P16}</td>
            <td style="text-align:center;font-family:verdanab">${task.Fecha_registro}</td>
        </tr>`;
    });
    $('#reporte').html(Template);
}

function renderPaginador() {
    const totalPaginas = Math.ceil(todosLosTasks.length / POR_PAGINA);
    if (totalPaginas <= 1) {
        $('#paginador').html('');
        return;
    }

    let html = '<div style="text-align:left;padding:10px;font-family:verdanab">';

    html += `<button class="btn-pag" data-pagina="${paginaActual - 1}" ${paginaActual === 1 ? 'disabled' : ''}>&laquo; Anterior</button>`;

    let inicio = Math.max(1, paginaActual - 2);
    let fin = Math.min(totalPaginas, inicio + 4);
    if (fin - inicio < 4) inicio = Math.max(1, fin - 4);

    if (inicio > 1) {
        html += `<button class="btn-pag" data-pagina="1">1</button>`;
        if (inicio > 2) html += `<span style="padding:0 5px">...</span>`;
    }

    for (let i = inicio; i <= fin; i++) {
        const activo = i === paginaActual ? 'background:#8a6d1f;color:#fff;font-weight:bold;' : '';
        html += `<button class="btn-pag" style="${activo}" data-pagina="${i}">${i}</button>`;
    }

    if (fin < totalPaginas) {
        if (fin < totalPaginas - 1) html += `<span style="padding:0 5px">...</span>`;
        html += `<button class="btn-pag" data-pagina="${totalPaginas}">${totalPaginas}</button>`;
    }

    html += `<button class="btn-pag" data-pagina="${paginaActual + 1}" ${paginaActual === totalPaginas ? 'disabled' : ''}>Siguiente &raquo;</button>`;

    const desde = (paginaActual - 1) * POR_PAGINA + 1;
    const hasta = Math.min(paginaActual * POR_PAGINA, todosLosTasks.length);
    html += `<div style="margin-top:8px;color:#666;font-size:13px;text-align:left">Mostrando ${desde} - ${hasta} de ${todosLosTasks.length} registros</div>`;

    html += '</div>';
    $('#paginador').html(html);
}

// 👇 ESTA ES LA QUE FALTABA
function irPagina(n) {
    const totalPaginas = Math.ceil(todosLosTasks.length / POR_PAGINA);
    if (n < 1 || n > totalPaginas) return;
    paginaActual = n;
    renderPagina();
    renderPaginador();
}

