                success: function (response) {
                const tasks = JSON.parse(response);
                let Template = '';
                tasks.forEach(task => {
                    Template += `
                    <tr id="textarea" taskId1="${task.id}" taskId2="${task.Nombre}">
                        <td id="borderout" style="padding:1em"><button class="editar_c" data-title="Editar" style="font-size:20px"><span class="fa fa-pencil"></span></button></td>
                        <td id="borderout" style="padding:1em"><button class="adjuntar_c" data-title="Editar" style="font-size:20px"><span class="fa fa-paperclip"></span></button></td>
                        <td id="borderout" align="center"><button class="pdf_reporte" style="color:${task.Carta}!important;font-size:22px"><span class="fa fa-check"></span></button></td>
                        <td style="text-align:center;font-family:verdanab">${task.numeracion}</td>
                        <td style="text-align:center;font-family:verdanab">${task.GES}</td>
                        <td style="text-align:center;font-family:verdanab;background:${task.R_C}">${task.Riesgo}</td>
