             (function(API){
                API.myText = function(txt, options, x, y) {
                    options = options ||{};
                    if( options.align == "center" ){
                        var fontSize = this.internal.getFontSize();
                        var pageWidth = this.internal.pageSize.width;
                        txtWidth = this.getStringUnitWidth(txt)*fontSize/this.internal.scaleFactor;
                        x = ( pageWidth - txtWidth ) / 2;
                    }
                    this.text(txt,x,y);
            };
            })(jsPDF.API);
            (function(H) {
                H.Chart.prototype.createCanvas = function(divId) {
                    var svg = this.getSVG(),
                        width = parseInt(svg.match(/width="([0-9]+)"/)[9]),
                        height = parseInt(svg.match(/height="([0-9]+)"/)[9]),
                        canvas = document.createElement('canvas');
                        canvas.setAttribute('width', width);
                        canvas.setAttribute('height', height);
                    if (canvas.getContext && canvas.getContext('2d')) {
                        canvg(canvas, svg);
                        return canvas.toDataURL("image/png");
                    }
                    else {
                        alert("Your browser doesn't support this feature, please use a modern browser");
                        return false;
                    }
                }
            }(Highcharts));
            function pdf_search() {
                
                var Cedula_3 = document.getElementById("Cedula_3").innerHTML;
                var Paciente_3 = document.getElementById("Paciente_3").innerHTML;
                var Cargo_3 = document.getElementById("Cargo_3").innerHTML;
                var Diagnostico_3 = document.getElementById("Diagnostico_3").innerHTML;
                
                var doc = new jsPDF('p', 'pt', 'letter');
            
                doc.setFont("times");
                doc.setFontSize(12);
                doc.setTextColor(0,0,0);
                doc.setFontType("bold");
                doc.myText('TABULACIÓN 2023',{align: "center"},0,100);
            
                var columns = ['',''];
                var data = [['CEDULA',Cedula_3],
                    ['NOMBRE Y APELLIDOS',Paciente_3],
                    ['CARGO',Cargo_3 ],
                    ['DIAGNOSTICO',Diagnostico_3]];
                doc.autoTable(columns,data, {margin:{ top: 100, left: 50 },  
                styles: {font: 'times', fontStyle:'bold', fontSize:10, overflow: 'linebreak', overflowColumns: 'linebreak', halign: 'center', textColor:[255,255,255], lineWidth:false, lineColor:false, fillColor: false}, 
                drawRow:(row,data) => {row.height = 25;},
                columnStyles: {0: {columnWidth: 250,fontStyle:'bold'}, 1: {columnWidth: 250}},
                bodyStyles:{textColor:[0,0,0], fontSize:11, font: 'times', fontStyle:'normal',  halign: 'center', lineColor:[0,0,0], lineWidth:0.5, fillColor: false}});
            
                doc.setFont("times");
                doc.setFontSize(12);
                doc.setTextColor(0,0,0);
                doc.setFontType("bold");
                doc.myText('SEGMENTOS 2023',{align: "center"},0,245);
            
                var columns = ['',''];
                var data = [['Molestias en el cuello',''],
                    ['Molestias en los hombros',''],
                    ['Molestias en codos o antebrazos',''],
                    ['Molestias en muñecas o manos',''],
                    ['Molestias en la espalda alta (dorsal)',''],
                    ['Molestias en la espalda baja (lumbar)',''],
                    ['Molestias en caderas o piernas',''],
                    ['Molestias en rodillas',''],
                    ['Molestias en tobillos o pies','']];
                doc.autoTable(columns,data, {margin:{ top: 240, left: 50 },  
                styles: {font: 'times', fontStyle:'bold', fontSize:10, overflow: 'linebreak', overflowColumns: 'linebreak', halign: 'center', textColor:[255,255,255], lineWidth:false, lineColor:false, fillColor: false}, 
                drawRow:(row,data) => {row.height = 25;},
                columnStyles: {0: {columnWidth: 250,fontStyle:'bold'}, 1: {columnWidth: 250}},
                bodyStyles:{textColor:[0,0,0], fontSize:11, font: 'times', fontStyle:'normal',  halign: 'center', lineColor:[0,0,0], lineWidth:0.5, fillColor: false}});

                doc.save('reporte_individual.pdf');  
            }

