// Abrir el modal al cargar la página y traer las notas
window.addEventListener('load', function () {
    // document.getElementById('notasModalOverlay').style.display = 'flex';
    cargarNotas();
});

// Cerrar con ESC
document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') {
        document.getElementById('notasModalOverlay').style.display = 'none';
    }
});

// ============================================================
// ============ CARGAR NOTAS ==================================
// ============================================================
function cargarNotas() {
    var Codigo = '<?php echo $Codigo ?>';
    const lista      = document.getElementById('notasLista');
    const contador   = document.getElementById('notasContador');      // ← Total de notas
    const pendientes = document.getElementById('notasPendientes');    // ← Solo pendientes
    const Pve = 4; // ← antes 2, ahora 4

    // === DIAGNÓSTICO (puedes borrar después) ===
    console.log('📤 Enviando → Codigo:', Codigo, '| Pve:', Pve, '| tipo Pve:', typeof Pve);

    $.post('../leer_notas.php', { Codigo: Codigo, Pve: Pve }, function (response) {

        // === DIAGNÓSTICO (puedes borrar después) ===
        console.log('📥 Respuesta cruda del servidor:', response);
        console.log('📥 Tipo de response:', typeof response);

        try {
            const res = (typeof response === 'string') ? JSON.parse(response) : response;

            // === DIAGNÓSTICO (puedes borrar después) ===
            console.log('📥 JSON parseado:', res);
            console.log('📥 total:', res.total, '| pendientes:', res.pendientes, '| notas:', res.notas);

            if (!res.ok) {
                console.error('❌ Error del servidor:', res.error);
                alert('Error del servidor: ' + res.error);
                return;
            }

            lista.innerHTML = '';

            // ===== Actualizar los dos conteos =====
            if (contador)   contador.textContent   = res.total;
            if (pendientes) pendientes.textContent = res.pendientes;

            if (res.notas.length === 0) {
                lista.innerHTML = '<div style="text-align:center;color:#999;font-size:13px;padding:20px 0;">No hay notas registradas</div>';
                return;
            }

            res.notas.forEach(function (n) {
                // ==== COLORES: ROJO SI NO ESTÁ DILIGENCIADA (0), AMARILLO SI SÍ (1) ====
                const diligenciada = Number(n.Diligenciada) === 1;
                const bgColor     = diligenciada ? '#fffbe6' : '#fdecea';  // amarillo muy claro vs rojo muy claro
                const borderColor = diligenciada ? '#f5d76e' : '#e74c3c';  // dorado claro vs rojo

                const nota = document.createElement('div');
                nota.style.cssText = 'display:flex;justify-content:space-between;align-items:flex-start;gap:10px;' +
                    'background:' + bgColor + ';' +
                    'border-left:3px solid ' + borderColor + ';' +
                    'border-radius:8px;padding:10px 12px;margin-bottom:8px;font-size:14px;line-height:1.4;';
                nota.dataset.id = n.id;

                // === Contenido ===
                const span = document.createElement('span');
                span.style.cssText = 'flex:1;word-break:break-word;';
                let contenido = n.Nota;

                if (n.Observacion && n.Observacion.trim() !== '') {
                    contenido += '<br><small style="color:#555;font-size:12px;display:block;margin-top:4px;">' +
                                 '<i class="fa fa-comment" style="color:' + borderColor + '"></i> ' +
                                 n.Observacion + '</small>';
                }

                contenido += '<br><small style="color:#999;font-size:11px;">' + n.Fecha_registro + '</small>';
                span.innerHTML = contenido;

                // === Botones ===
                const btnContainer = document.createElement('div');
                btnContainer.style.cssText = 'display:flex;gap:4px;align-items:flex-start;';

                // Botón eliminar
                const btnEliminar = document.createElement('button');
                btnEliminar.innerHTML = '&times;';
                btnEliminar.title = 'Eliminar nota';
                btnEliminar.style.cssText = 'background:transparent;border:none;color:#999;font-size:18px;line-height:1;cursor:pointer;padding:0 4px;transition:color 0.2s;';
                btnEliminar.onmouseover = function () { this.style.color = '#e74c3c'; };
                btnEliminar.onmouseout  = function () { this.style.color = '#999'; };
                btnEliminar.onclick     = function () { eliminarNota(n.id, nota); };

                // Botón observación
                const btnObs = document.createElement('button');
                btnObs.innerHTML = '<i class="fa fa-comment"></i>';
                btnObs.title = 'Agregar observación';
                btnObs.style.cssText = 'background:transparent;border:none;color:#999;font-size:14px;line-height:1;cursor:pointer;padding:0 4px;transition:color 0.2s;';
                btnObs.onmouseover = function () { this.style.color = '#e6b800'; };
                btnObs.onmouseout  = function () { this.style.color = '#999'; };
                btnObs.onclick     = function () { agregarObservacion(n.id); };

                // Botón confirmar
                const btnConfirmar = document.createElement('button');
                btnConfirmar.innerHTML = '<i class="fa fa-check"></i>';
                btnConfirmar.title = 'Confirmar (marcar como diligenciada)';
                btnConfirmar.style.cssText = 'background:transparent;border:none;color:#999;font-size:14px;line-height:1;cursor:pointer;padding:0 4px;transition:color 0.2s;';
                btnConfirmar.onmouseover = function () { this.style.color = '#27ae60'; };
                btnConfirmar.onmouseout  = function () { this.style.color = '#999'; };
                btnConfirmar.onclick     = function () { confirmarNota(n.id); };

                btnContainer.appendChild(btnEliminar);
                btnContainer.appendChild(btnObs);
                btnContainer.appendChild(btnConfirmar);

                nota.appendChild(span);
                nota.appendChild(btnContainer);
                lista.appendChild(nota);
            });

        } catch (e) {
            console.error('❌ Respuesta inválida:', response);
            console.error('❌ Error capturado:', e);
        }
    });
}

// ============================================================
// ============ AGREGAR NOTA ==================================
// ============================================================
function agregarNota() {
    var Codigo = '<?php echo $Codigo ?>';
    const notas = $('#notasInput').val().trim();
    if (notas === '') {
        $('#notasInput').focus();
        return;
    }
    const postData = {
        Codigo: Codigo,
        notas: notas,
        Pve: 4      
    };
    $.post('../insertar_notas.php', postData, function (response) {
        $('#notasInput').val('');
        cargarNotas();
    });
}

// ============================================================
// ============ ELIMINAR NOTA =================================
// ============================================================
function eliminarNota(id, elemento) {
    if (!confirm('¿Eliminar esta nota?')) return;

    $.post('../eliminar_nota.php', { id: id }, function (response) {
        try {
            const res = (typeof response === 'string') ? JSON.parse(response) : response;
            if (res.ok) {
                elemento.remove();
                actualizarContador();
            } else {
                alert('Error: ' + res.error);
            }
        } catch (e) {
            console.error(response);
        }
    });
}

// ============================================================
// ============ ACTUALIZAR CONTADOR ===========================
// ============================================================
function actualizarContador() {
    const total = document.querySelectorAll('#notasLista > div[data-id]').length;
    document.getElementById('notasContador').textContent = total;
}

// ============================================================
// ============ AGREGAR OBSERVACIÓN ===========================
// ============================================================
function agregarObservacion(id) {
    const obs = prompt('Escribe la observación:');
    if (obs === null) return;
    if (obs.trim() === '') {
        alert('La observación no puede estar vacía');
        return;
    }

    $.post('../actualizar_observacion.php', { id: id, observacion: obs.trim() }, function (response) {
        try {
            const res = (typeof response === 'string') ? JSON.parse(response) : response;
            if (res.ok) {
                cargarNotas();
            } else {
                alert('Error: ' + res.error);
            }
        } catch (e) {
            console.error(response);
        }
    });
}

// ============================================================
// ============ CONFIRMAR NOTA ================================
// ============================================================
function confirmarNota(id) {
    if (!confirm('¿Marcar esta nota como diligenciada?')) return;

    $.post('../confirmar_nota.php', { id: id }, function (response) {
        try {
            const res = (typeof response === 'string') ? JSON.parse(response) : response;
            if (res.ok) {
                cargarNotas();
            } else {
                alert('Error: ' + res.error);
            }
        } catch (e) {
            console.error(response);
        }
    });
}
